const $=s=>document.querySelector(s);
let seed=72948, year=10, zoom=100, events=24, entropy=67;
function rng(s){return()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2100)}
function drawMap(){const c=$('#mapCanvas'),x=c.getContext('2d'),W=c.width,H=c.height,random=rng(seed);const cols=36,rows=17,w=W/cols,h=H/rows; x.clearRect(0,0,W,H); let tiles=[]; for(let y=0;y<rows;y++){tiles[y]=[];for(let i=0;i<cols;i++){let v=random(), edge=(i<2||y<1||i>33||y>15);let type=edge?'water':v<.09?'water':v<.16?'mountain':v<.34?'forest':v<.39?'sand':'grass';tiles[y][i]=type;let colors={water:'#294b59',grass:'#486947',forest:'#31594b',mountain:'#6c7274',sand:'#817052'};x.fillStyle=colors[type];x.fillRect(i*w,y*h,w+1,h+1);if(type==='forest'){x.fillStyle='#25483d';x.fillRect(i*w+w*.35,y*h+h*.2,2,7);x.fillRect(i*w+w*.6,y*h+h*.5,2,6)}if(type==='mountain'){x.fillStyle='#858b8a';x.beginPath();x.moveTo(i*w,y*h+h);x.lineTo(i*w+w*.5,y*h+5);x.lineTo(i*w+w,y*h+h);x.fill()}}}x.strokeStyle='#ffffff0b';x.lineWidth=1;for(let i=0;i<=cols;i++){x.beginPath();x.moveTo(i*w,0);x.lineTo(i*w,H);x.stroke()}for(let j=0;j<=rows;j++){x.beginPath();x.moveTo(0,j*h);x.lineTo(W,j*h);x.stroke()}let px=19*w,py=8*h;x.strokeStyle='#d5a779';x.fillStyle='#edb984';x.lineWidth=2;x.beginPath();x.arc(px,py,8,0,Math.PI*2);x.stroke();x.beginPath();x.moveTo(px,py+8);x.lineTo(px,py+17);x.stroke();x.fillRect(px-2,py-2,4,4)}
function drawAvatar(){const c=$('#avatarCanvas'),x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.imageSmoothingEnabled=false;const p=(fill,rx,ry,rw,rh)=>{x.fillStyle=fill;x.fillRect(rx,ry,rw,rh)};p('#1c2035',44,25,103,159);p('#292a42',58,55,76,108);p('#d99b76',75,47,43,47);p('#eab087',80,53,34,32);p('#3c2945',71,38,51,18);p('#3c2945',70,42,12,30);p('#3c2945',111,42,13,28);p('#242237',74,83,45,33);p('#9e6dcb',67,88,59,58);p('#69488e',63,102,10,39);p('#69488e',120,102,10,39);p('#25233b',72,145,22,44);p('#25233b',105,145,22,44);p('#e7a974',78,68,6,5);p('#e7a974',108,68,6,5);p('#30233e',88,82,17,3);p('#dfaf77',83,116,29,6);p('#bd7d6a',58,120,7,30);p('#bd7d6a',126,120,7,30);x.strokeStyle='#f0bd82';x.lineWidth=2;x.beginPath();x.moveTo(67,110);x.lineTo(57,128);x.lineTo(67,138);x.moveTo(125,110);x.lineTo(138,127);x.stroke();p('#d5a46f',48,152,23,5);p('#d5a46f',119,152,23,5)}
function updateYear(v){year=+v;$('#yearStat').textContent=year;$('#timelineYear').textContent=year;$('#yearSlider').value=year;const e=Math.max(0,year-10);$('#entropyStat').innerHTML=(entropy+e*3)+'<span>%</span>';if(year>10)$('#newLine').textContent=`ANO ${year} — O futuro ainda está sendo escrito...`;else $('#newLine').textContent=''}
function newSeed(){seed=Math.floor(Math.random()*900000)+100000;$('#seedValue').textContent=seed;$('#seedStat').textContent=seed;drawMap();showToast('Nova semente gerada: '+seed)}
$('#yearSlider').addEventListener('input',e=>updateYear(e.target.value));$('#newSeed').addEventListener('click',newSeed);$('#regenBtn').addEventListener('click',()=>{drawMap();showToast('Tilemap regenerado com a semente atual.')});$('#simulateBtn').addEventListener('click',()=>{if(year<15){updateYear(year+1);events++;entropy=Math.min(99,entropy+3);$('#eventStat').textContent=events;showToast('Ano '+year+' simulado. Uma nova consequência surgiu.')}else showToast('A cronologia planejada chegou ao fim.')});$('#rollBtn').addEventListener('click',()=>{const titles=['O sino sob as raízes','A cartógrafa desaparecida','Um pacto em águas rasas','As estrelas mudam de lugar'];const n=Math.floor(rng(Date.now())()*titles.length);document.querySelector('.event-body h3').textContent=titles[n];showToast('Destino rolado: evento recalculado.')});$('#zoomIn').addEventListener('click',()=>{zoom=Math.min(200,zoom+10);$('#zoomLevel').textContent=zoom+'%';$('#mapCanvas').style.transform=`scale(${zoom/100})`;});$('#zoomOut').addEventListener('click',()=>{zoom=Math.max(70,zoom-10);$('#zoomLevel').textContent=zoom+'%';$('#mapCanvas').style.transform=`scale(${zoom/100})`});$('#saveBtn').addEventListener('click',()=>{localStorage.setItem('pixelSagaSave',JSON.stringify({seed,year,events,entropy}));showToast('Mundo salvo localmente.')});$('#exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({seed,year,events,entropy},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lumen-world.json';a.click();showToast('Arquivo de mundo exportado.')});$('#placeBtn').addEventListener('click',()=>{showToast('Juno posicionada no Vale de Cinzas.')});$('#editCharacter').addEventListener('click',()=>showToast('Ficha de Juno pronta para edição.'));$('#addLineBtn').addEventListener('click',()=>{$('#newLine').textContent='NOVA NOTA — Uma escolha aguarda sua intervenção.';showToast('Linha adicionada ao console.')});
drawMap();drawAvatar();updateYear(year);
